// The VHP ruler's workflow (.github/workflows/vhp-ruler.yml, generated by tools/vhp-ruler-workflow.mjs): step (e) of
// R-RULER-1. The publish job runs no repository code; its embedded Python is vhp_ruler.py byte for byte; its shell
// and Python are run here, as the runner runs them, against a scratch repository standing in for GitHub.
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync, spawnSync } from "node:child_process";
import { APP, D, makeChain } from "./vhp-ruler.fixture.mjs";

const YML = path.join(APP, ".github/workflows/vhp-ruler.yml");
const jobs = JSON.parse(execFileSync("python3", ["-c", "import yaml,json,sys; w=yaml.safe_load(open(sys.argv[1])); print(json.dumps(w['jobs']))", YML], { encoding: "utf8" }));
const publishRun = jobs.publish.steps.map((s) => s.run || "").find((r) => r.includes("<<'PY'"));
const TRAILER = "\nimport sys\nsys.exit(publish_main(sys.argv[1:]))\n";

test("the workflow file is what the generator writes, and its Python is vhp_ruler.py byte for byte", () => {
  const before = fs.readFileSync(YML, "utf8");
  execFileSync("node", [path.join(APP, "tools/vhp-ruler-workflow.mjs")], { encoding: "utf8" });
  assert.equal(fs.readFileSync(YML, "utf8"), before, "run node tools/vhp-ruler-workflow.mjs after changing vhp_ruler.py");
  const py = publishRun.slice(publishRun.indexOf("<<'PY'\n") + 7, publishRun.indexOf("\nPY\n") + 1);
  assert.equal(py, fs.readFileSync(path.join(APP, "vhp_ruler.py"), "utf8") + TRAILER);
});

test("the publish job runs no repository code; only it can write; every job is off until the owner turns it on", () => {
  const shell = publishRun.slice(0, publishRun.indexOf("<<'PY'")) + publishRun.slice(publishRun.indexOf("\nPY\n"));   // without the embedded Python
  const uses = jobs.publish.steps.map((s) => s.uses || "").join(" ");
  assert.doesNotMatch(shell + uses, /actions\/checkout|\bnpm |\bnpx |\btsx\b|\bnode |\.\/[a-z]/, "no checkout, no node, no repository script");
  assert.equal(jobs.publish.permissions.contents, "write");
  for (const [name, j] of Object.entries(jobs)) {
    if (name !== "publish") assert.equal(j.permissions.contents, "read", `${name} is read-only`);
    if (j.if) assert.match(j.if, /vars\.VHP_RULER_ENABLED == 'true'/, `${name}: off by default`);
    if (j.if) assert.match(j.if, /github\.ref == 'refs\/heads\/main'/, `${name}: main only`);
  }
  assert.doesNotMatch(fs.readFileSync(YML, "utf8"), /secrets\./, "no secrets anywhere");
  assert.match(publishRun, /git push -q "\$remote" "\$commit:refs\/heads\/vhp-data"/, "pushes vhp-data, nothing else");
});

// ── the publish step, run for real against a local bare repository ──
const sandbox = fs.mkdtempSync(path.join(os.tmpdir(), "vhp-publish-"));
const bare = path.join(sandbox, "origin.git");
execFileSync("git", ["init", "-q", "--bare", bare]);
const script = publishRun.replace(/remote="https:\/\/x-access-token:\$\{GH_TOKEN\}@github\.com\/\$\{GITHUB_REPOSITORY\}\.git"/, `remote="${bare}"`);
assert.notEqual(script, publishRun, "the test points the push at the scratch repository");
let runNo = 0;
function publish(files, remove) {
  const dir = path.join(sandbox, `run${++runNo}`), IN = path.join(dir, "incoming");
  fs.mkdirSync(IN, { recursive: true });
  for (const [p, t] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(IN, p)), { recursive: true }); fs.writeFileSync(path.join(IN, p), t); }
  if (remove) fs.writeFileSync(path.join(IN, "remove.txt"), remove.join("\n") + "\n");
  const r = spawnSync("bash", ["-c", script], { cwd: dir, env: { ...process.env, RUNNER_TEMP: dir, IN, KEEP: "30", GH_TOKEN: "x", GITHUB_REPOSITORY: "o/r" }, encoding: "utf8" });
  return { ok: r.status === 0, out: r.stdout + r.stderr };
}
const branch = () => { try { return execFileSync("git", ["-C", bare, "ls-tree", "-r", "--name-only", "vhp-data"], { encoding: "utf8" }).trim().split("\n").filter(Boolean); } catch { return []; } };
const head = () => { try { return execFileSync("git", ["-C", bare, "rev-parse", "vhp-data"], { encoding: "utf8" }).trim(); } catch { return ""; } };

const g = makeChain({ seed: 41, hours: 99, np: 3, n0: 33480, busy: 0.01 });   // 33,480 = day 1,395 × 24
const hf = (i) => ({ [`h/${33480 + i}.json`]: g.texts[i] });
const many = (a, b) => Object.assign({}, ...Array.from({ length: b - a }, (_, k) => hf(a + k)));

test("publish: the first hours (a chain from the start), then more; each run adds a commit to vhp-data", () => {
  let r = publish(many(0, 3)); assert.equal(r.ok, true, r.out);
  assert.deepEqual(branch(), ["h/33480.json", "h/33481.json", "h/33482.json"]);
  const c1 = head();
  r = publish(many(3, 5)); assert.equal(r.ok, true, r.out);
  assert.equal(branch().length, 5);
  assert.equal(execFileSync("git", ["-C", bare, "rev-parse", "vhp-data^"], { encoding: "utf8" }).trim(), c1, "the new commit's parent is the last one");
});

test("publish refuses: a tampered hour, a gap, a rewrite, a stray file, a non-canonical file — and vhp-data doesn't move", () => {
  const before = head();
  const bad = JSON.parse(g.texts[5]); bad.burns[300] = String(BigInt(bad.burns[300]) - 1n);   // past the previous hour's tail
  for (const [files, why] of [
    [{ "h/33485.json": D.canon(bad) }, /previous anchor plus the changes/],
    [hf(6), /first new hour must be h\/33485/],
    [{ "h/33484.json": g.texts[3] }, /can't be rewritten/],
    [{ ...hf(5), "x.txt": "hi" }, /unexpected files/],
    [{ "h/33485.json": g.texts[5].replace(/\n$/, "  \n") }, /canonical/],
  ]) {
    const r = publish(files);
    assert.equal(r.ok, false, `should refuse: ${why}`); assert.match(r.out, why);
    assert.equal(head(), before, "nothing pushed");
  }
});

test("publish: a day rollup replaces its hours; removals need a day file; days go only after retention", () => {
  let r = publish(many(5, 72)); assert.equal(r.ok, true, r.out);
  r = publish({}, ["h/33490.json"]);
  assert.equal(r.ok, false); assert.match(r.out, /no day file holds it/);
  const day = D.makeDay(1395, g.texts.slice(0, 24));
  r = publish({ "d/1395.json": day }, Array.from({ length: 24 }, (_, i) => `h/${33480 + i}.json`));
  assert.equal(r.ok, true, r.out);
  const files = branch();
  assert.ok(files.includes("d/1395.json") && !files.includes("h/33480.json") && files.includes("h/33504.json"));
  r = publish(hf(72)); assert.equal(r.ok, true, `the chain still checks after the rollup: ${r.out}`);
  r = publish({}, ["d/1395.json"]);
  assert.equal(r.ok, false); assert.match(r.out, /still inside the 30 days kept/);
  const changed = JSON.parse(day); changed.hours[3].ids[0] = changed.hours[3].ids[1];
  r = publish({ "d/1396.json": D.makeDay(1396, g.texts.slice(24, 48)).replace(g.texts[30].slice(10, 40), g.texts[31].slice(10, 40)) });
  assert.equal(r.ok, false, "a day file whose hours differ from the published ones is refused");
});

test("recompute_main: a game's publish job can check a card against vhp-data (and refuses a changed one)", async () => {
  const { R } = await import("./vhp-ruler.fixture.mjs");
  const dir = path.join(sandbox, "data"); fs.mkdirSync(path.join(dir, "h"), { recursive: true });
  g.texts.slice(0, 40).forEach((t, i) => fs.writeFileSync(path.join(dir, "h", `${33480 + i}.json`), t));
  const L = R.ledger(D.timelineFrom(g.texts.slice(0, 40).map((t) => JSON.parse(t)), g.texts.slice(0, 40).map((t, i) => D.checkHour(i ? g.texts[i - 1] : "", t))));
  const Lk = L.from + 36000;
  const card = R.cardJson(R.scoreCard(L, R.makeCard(L, { game: 7, round: "1", window: { W0: Lk - 7199, W1: Lk, L: Lk, S0: Lk + 1, S1: Lk + 1200 }, c: 0n, ownRule: "spot", paying: false })));
  fs.writeFileSync(path.join(sandbox, "card.json"), card);
  const run = (f) => spawnSync("python3", ["-I", "-B", "-c", `import sys; sys.path.insert(0, ${JSON.stringify(APP)}); import vhp_ruler as V; sys.exit(V.recompute_main(sys.argv[1:]))`, dir, f], { encoding: "utf8" });
  assert.equal(run(path.join(sandbox, "card.json")).status, 0);
  fs.writeFileSync(path.join(sandbox, "card2.json"), card.replace(/"signed":(\d+)/, (m, d) => `"signed":${+d + 1}`));
  assert.equal(run(path.join(sandbox, "card2.json")).status, 1);
});
